public int[] answerQueries(int n, int[][] edges, int[][] queries) {
    List<List<int[]>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) adj.get(e[0]).add(new int[]{e[1], e[2]});   // directed
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
        int src = queries[qi][0], dst = queries[qi][1];
        long[] dist = new long[n + 1];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[src] = 0;
        PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        heap.offer(new long[]{0, src});
        while (!heap.isEmpty()) {
            long[] top = heap.poll();
            long d = top[0];
            int u = (int) top[1];
            if (d > dist[u]) continue;
            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    heap.offer(new long[]{dist[v], v});
                }
            }
        }
        ans[qi] = dist[dst] == Long.MAX_VALUE ? -1 : (int) dist[dst];
    }
    return ans;
}

