import heapq

def answer_queries(self, n: int, edges: list[list[int]], queries: list[list[int]]) -> list[int]:
    adj: list[list[tuple[int, int]]] = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        adj[u].append((v, w))             # directed
    INF = float('inf')
    out: list[int] = []
    for src, dst in queries:
        dist = [INF] * (n + 1)
        dist[src] = 0
        heap = [(0, src)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        out.append(-1 if dist[dst] == INF else dist[dst])
    return out

