public int[] answerQueries(int n, int[][] edges, int[][] queries) {
    final long INF = Long.MAX_VALUE / 4;       // safe sentinel, no overflow on a sum
    long[][] dist = new long[n + 1][n + 1];
    for (long[] row : dist) Arrays.fill(row, INF);
    for (int i = 1; i <= n; i++) dist[i][i] = 0;
    for (int[] e : edges) {
        dist[e[0]][e[1]] = Math.min(dist[e[0]][e[1]], e[2]);   // directed, keep min parallel
    }
    for (int k = 1; k <= n; k++) {             // intermediate node — OUTERMOST
        for (int i = 1; i <= n; i++) {
            if (dist[i][k] == INF) continue;   // no point routing through k
            for (int j = 1; j <= n; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
        long d = dist[queries[qi][0]][queries[qi][1]];
        ans[qi] = d >= INF ? -1 : (int) d;
    }
    return ans;
}

