def answer_queries(self, n: int, edges: list[list[int]], queries: list[list[int]]) -> list[int]:
    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)        # directed, keep min parallel
    for k in range(1, n + 1):                  # intermediate node — OUTERMOST
        dk = dist[k]
        for i in range(1, n + 1):
            dik = dist[i][k]
            if dik == INF:
                continue                       # no path into k from i
            di = dist[i]
            for j in range(1, n + 1):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd
    out: list[int] = []
    for a, b in queries:
        d = dist[a][b]
        out.append(-1 if d == INF else d)
    return out

